window.FILM_WORK_PROMPTS={"work_id":"src-92aaebbece9a1f34","records":[{"work_id":"src-92aaebbece9a1f34","frame_id":"FG-dd77276f2bece5e5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Excision_006.jpg","source_page":"https://film-grab.com/2019/10/01/excision/","scene":"金发女性上半身位于画面中央，背景左侧为贴有儿童画作的白色墙面，右侧可见黄色窗帘与绿色植物，室内光线明亮。","analysis":"人物占据画面中心约三分之一宽度，头部至胸部可见，面部朝向右侧。背景左侧白墙上有彩色磁贴固定的画作，右侧黄色窗帘占据约四分之一画面宽度。光线从右侧窗户射入，形成柔和的侧光，人物面部受光均匀，阴影柔和。","prompt":"金发女性上半身正面偏右，长发垂落肩部，身穿深色带点状图案上衣，面部表情平静略带困惑，视线向右。背景左侧白色墙面上贴有儿童画作，画作上有蓝色花朵和绿色植物图案，用彩色磁贴固定，下方可见红色十字图案。右侧黄色半透明窗帘垂落，窗帘旁有绿色植物叶片。室内自然光从右侧窗户射入，光线柔和明亮，整体色调温暖。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:01:26-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Excision_006.jpg","observed_dimensions":[1280,533],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.501,"observed_resolution":"normal","observation_limits":[],"id":"VP-61c3ce060b366f9a","origin":"visual"},{"work_id":"src-92aaebbece9a1f34","frame_id":"FG-9604227f4881442e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Excision_016.jpg","source_page":"https://film-grab.com/2019/10/01/excision/","scene":"金发女性上半身正面可见，端坐于深色高背椅中，背景为大面积深灰暗色空间，左下角有模糊玻璃杯边缘。","analysis":"人物面部及肩颈占据画面中心，头部至胸部清晰，长发垂落两侧。背景极度简化，仅见椅背尖角轮廓。光线从正前方偏上投射，面部受光均匀，眼窝与颈部形成阴影，发丝边缘有微弱轮廓光。整体色调冷暗，仅唇部红色与颈部黑色珠链形成局部色彩对比。","prompt":"金发女性正面端坐，上半身可见，长发中分垂落肩前，面部表情严肃，嘴唇微张涂深红唇膏，颈部佩戴黑色串珠项链，身着深色外套内搭暗红色衣物。身后是深色高背椅，椅背两侧有尖角突起。背景为均匀的深灰黑色，无其他杂物。左下角前景处有一个模糊的透明玻璃杯边缘。光线从正前方偏上照射，面部明亮，背景沉入黑暗，整体氛围压抑冷峻。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:01:33-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Excision_016.jpg","observed_dimensions":[1280,533],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.415,"observed_resolution":"normal","observation_limits":[],"id":"VP-73c1e1e2d4bfebcb","origin":"visual"},{"work_id":"src-92aaebbece9a1f34","frame_id":"FG-5ce7478a4b216919","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Excision_027.jpg","source_page":"https://film-grab.com/2019/10/01/excision/","scene":"黑色背景上，五个人物以俯视角度紧密排列成十字形，中心人物头部被遮挡，周围人物身体向外延伸，形成向心结构。","analysis":"构图采用俯视视角，人物身体呈放射状分布，中心人物仅露出头顶，周围四人身体部分可见。光线从上方投射，人物皮肤与白色衣物形成明暗对比，黑色背景占据画面大部分，突出人物轮廓。","prompt":"俯视视角，黑色背景，五个人物紧密排列成十字形，中心人物头部被遮挡，周围四人身体向外延伸，左侧人物卷发，右侧人物穿白色短裤，下方人物穿白色抹胸，上方人物背部裸露，人物皮肤在光线下呈现自然色泽，白色衣物与黑色背景形成强烈对比，整体构图紧凑，人物姿态静止。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:01:39-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Excision_027.jpg","observed_dimensions":[1280,533],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.426,"observed_resolution":"normal","observation_limits":[],"id":"VP-5416b2320d72dcde","origin":"visual"},{"work_id":"src-92aaebbece9a1f34","frame_id":"FG-fa81b934e5e83688","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Excision_037.jpg","source_page":"https://film-grab.com/2019/10/01/excision/","scene":"蓝白瓷砖浴室中，左侧前景为模糊的深发女子侧脸，右侧镜中清晰映出该女子被金属器械撑开嘴部，旁边站着一位金发白衣戴手套的人物。","analysis":"画面采用前景虚化与镜中实焦的对比构图。左侧前景人物仅见头部与肩部，处于失焦状态。右侧镜面反射出清晰的中景画面，深发女子身着白色抹胸，金发人物身着白色高领长袖并佩戴白手套，手持金属长柄器械伸入前者口中。背景为蓝白相间的方形瓷砖墙面，光线明亮均匀，冷色调为主。","prompt":"蓝白方格瓷砖墙面的浴室场景，画面左侧前景是一个失焦模糊的深褐色马尾辫女子侧脸，占据画面左半部分。右侧是一面金属边框的镜子，镜中清晰反射出该女子身穿白色抹胸，正被右侧一位金发齐刘海、身穿白色高领长袖紧身衣并戴白手套的人物用金属长柄器械撑开嘴部。镜中人物神情冷静，背景是明亮的蓝白瓷砖，整体色调冷冽，光影清晰，呈现出一种紧张且压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:01:46-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Excision_037.jpg","observed_dimensions":[1280,533],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.525,"observed_resolution":"normal","observation_limits":[],"id":"VP-9ff0f4e69c6c9776","origin":"visual"},{"work_id":"src-92aaebbece9a1f34","frame_id":"FG-24b521139a74b967","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Excision_047.jpg","source_page":"https://film-grab.com/2019/10/01/excision/","scene":"长发人物身穿红色宽松上衣，盘腿坐在浴室地面的深蓝色垫子上，面前摆放着瓶罐等杂物，周围是米黄色瓷砖墙壁和黑色地砖。","analysis":"画面采用平视视角，人物位于画面中央，全身可见，呈盘腿坐姿。环境占据大部分画面，左侧可见白色门框，右侧为米色浴缸边缘。光线柔和，整体色调偏暖，红色上衣在暗色背景和米色墙壁的衬托下十分醒目。","prompt":"一位留着深色长发的年轻人物，身穿宽松的红色长袖上衣和深色裤子，盘腿坐在浴室地面的深蓝色长方形地垫上。人物双手自然垂放于两腿之间，面部表情平静。地垫前方散落着几个白色和粉色的小圆盒、一个白色塑料瓶以及一团白色纸巾。背景是米黄色的方形瓷砖墙壁，地面铺设着黑色菱形地砖。画面左侧是一扇白色的门，右侧前景可见米色浴缸的边缘。整体光线柔和，色彩以暖色调为主，营造出一种安静、私密的室内氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T15:01:53-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/Excision_047.jpg","observed_dimensions":[1280,533],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.492,"observed_resolution":"normal","observation_limits":[],"id":"VP-6b0c982d50711089","origin":"visual"}]};